/*
 * modules/static/server.js — srvctl static/emergency file server.
 *
 * Root-run Node.js HTTP daemon on port 1280 (all interfaces), executed
 * in place by static-server.service (generated by
 * hooks/update-install-host.sh). Serves files on demand from
 * /var/srvctl3/storage/static/<host-header>/html — docroots seeded by
 * libs/regenerate.sh. Plain HTTP by design: the old pound proxy could
 * not serve emergency pages itself. On-demand serve-static was chosen
 * over res.sendFile or in-memory caching; measurement showed a file
 * served within ~0.150ms.
 *
 * FIXME(v4): orphaned — nothing routes to :1280 anymore (haproxy's
 * default backend is localhost:1282, the default module, and pound is
 * gone); wire it back in as the emergency backend or drop it, merging
 * with the near-identical modules/default/server.js.
 */

// FIXME(v4): hard-coded /usr/lib/node_modules paths depend on the npm -g
// prefix used by hooks/update-install-host.sh; a different prefix
// (/usr/local) breaks startup into a Restart=always crash loop.
var finalhandler = require('/usr/lib/node_modules/finalhandler');
var http = require('http');
var serveStatic = require('/usr/lib/node_modules/serve-static');

var server = http.createServer(function onRequest(req, res) {

    // Log one greppable line per request: host url user-agent x-forwarded-for
    console.log(req.headers.host, req.url, req.headers['user-agent'], req.headers['x-forwarded-for']);

    // Host normalization: undefined Host falls back to d250.hu; leading
    // "www." and "static." prefixes map to the bare domain's docroot.
    var host = req.headers.host;
    if (host === undefined) {
        console.log("undefined host in req.headers:", req.headers);
        host = "d250.hu";
    }
    // FIXME(v4): the "static." strip reads req.headers.host instead of
    // the already-www-stripped host: "www.static.example.com" yields
    // "tic.example.com" (wrong docroot, 404); an explicit :port suffix
    // is never stripped either.
    if (host.substring(0, 4) === 'www.') host = req.headers.host.substring(4);
    if (host.substring(0, 7) === 'static.') host = req.headers.host.substring(7);

    // FIXME(v4): res.send does not exist on http.ServerResponse (it is
    // an Express API) — any serve-static error (e.g. malformed percent-
    // encoding in the URL) throws in this deferred callback, the
    // uncaught TypeError kills the whole process and Restart=always
    // flaps the service. The second res.send also runs unconditionally
    // (no else/return), so even the err-falsy path would crash.
    var done = finalhandler(req, res, {
        onerror: function(err, req, res) {
            if (err) {
                console.log(err.toString());
                res.send('error', err.statusCode);
            }
            res.send('error', "undefined");
        }
    });

    // FIXME(v4): docroot built from the unvalidated Host header — '/'
    // and '.' are legal in header values, so 'Host: ../../..<path>'
    // escapes the storage tree and this root process serves any readable
    // directory ending in /html; serve-static only guards traversal in
    // the URL path, not in the root it is given. v4: allowlist hosts
    // against the datastore container list.
    var serve = serveStatic('/var/srvctl3/storage/static/' + host + '/html');
    serve(req, res, done);

});
// Listen
server.listen(1280);
console.log("srvctl static-server started");
